/**
 * Locks a member out of the workspace without touching their role or seat.
 * Guarded the same way `removeMember` is, plus two rules removal does not
 * have: nobody may suspend themselves or a member who outranks them, and the
 * workspace must keep at least one owner who is not suspended.
 */
export async function suspendMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (isArchived(member)) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  assertMayActOn(actor, member, "suspend");

  if (member.status === "suspended") return member;

  await assertSuspendingRetainsOwner(input.orgId, member);

  const suspended = await memberRepo.suspendMember(input.orgId, input.memberId);

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Reverses `suspendMember`. Never threatened by the last-owner rule. */
export async function reinstateMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (isArchived(member)) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  assertMayActOn(actor, member, "reinstate");

  if (member.status !== "suspended") return member;

  const reinstated = await memberRepo.reinstateMember(input.orgId, input.memberId);

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/** Nobody may target themselves or a member whose role outranks their own. */
function assertMayActOn(
  actor: Actor,
  member: Member,
  verb: "suspend" | "reinstate",
): void {
  if (member.userId === actor.userId) {
    throw new Error(`You cannot ${verb} yourself`);
  }
  if (ROLE_RANK[member.role] > ROLE_RANK[actor.role]) {
    throw new Error(`A ${actor.role} cannot ${verb} a ${member.role}`);
  }
}

/**
 * Suspending an owner is refused when it would leave the organization without
 * an owner who can actually act — a suspended owner does not keep the
 * workspace ownable.
 */
async function assertSuspendingRetainsOwner(
  orgId: OrgId,
  member: Member,
): Promise<void> {
  if (member.role !== "owner") return;

  const remaining = await countOtherActiveOwners(orgId, member.id);
  if (remaining === 0) {
    throw new Error(
      "An organization must keep at least one owner who is not suspended; transfer ownership first",
    );
  }
}

/** Live, non-suspended owners other than `excludeMemberId`. */
async function countOtherActiveOwners(
  orgId: OrgId,
  excludeMemberId: MemberId,
): Promise<number> {
  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    status: "active",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  return page.items.filter((row) => row.id !== excludeMemberId).length;
}

